// MANDATORY Postgres-before-binary-consumer pattern: the Postgres node above
// replaced the item and dropped item.binary. Re-establish it ONCE, by node
// reference from the trigger, directly before the consumer.
return [{ json: $json, binary: $('When Called by WF-001').first().binary }];

// SW-029 — compute the storage key and validate the bytes before any upload.
//
// Content type and extension come from MAGIC BYTES, never from the Drive
// mimeType (finding: probe E). The date partition comes from
// documents.uploaded_at, never from wall-clock (finding H2).

const trig = $('When Called by WF-001').first().json;
const row  = $json || {};

if (!row.document_id) {
  throw new Error('SW-029: no repository.documents row for documentId=' +
    (trig.documentId || '(missing)') + '. Register the document before persisting its original.');
}

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!buf || buf.length === 0) {
  throw new Error('SW-029: binary property "data" is empty or absent — the original file did not cross the workflow boundary.');
}
const byteSize = buf.length;

// --- magic-byte sniff -> { contentType, ext } ---
const hex = (n) => buf.slice(0, n).toString('hex').toUpperCase();
let contentType = null, ext = null;
if (buf.slice(0, 4).toString('latin1') === '%PDF')            { contentType = 'application/pdf';  ext = 'pdf'; }
else if (hex(8) === '89504E470D0A1A0A')                        { contentType = 'image/png';        ext = 'png'; }
else if (hex(3) === 'FFD8FF')                                  { contentType = 'image/jpeg';       ext = 'jpg'; }
else if (hex(4) === '49492A00' || hex(4) === '4D4D002A')        { contentType = 'image/tiff';       ext = 'tiff'; }

if (!contentType) {
  throw new Error('SW-029: unsupported or unrecognised file type (first bytes ' + hex(8) +
    '). Refusing to store an object whose extension cannot be derived from its content.');
}

// --- size gate (H6): fail here, not after the expensive OCR step ---
const maxBytes = Number($env.CRIE_STORAGE_MAX_BYTES) || 0;
if (maxBytes > 0 && byteSize > maxBytes) {
  throw new Error('SW-029: file is ' + byteSize + ' bytes, above CRIE_STORAGE_MAX_BYTES=' + maxBytes + '.');
}

const endpoint = ($env.CRIE_STORAGE_ENDPOINT || '').replace(/\/+$/, '');
const bucket   = $env.CRIE_STORAGE_BUCKET || '';
if (!endpoint || !bucket) {
  throw new Error('SW-029: CRIE_STORAGE_ENDPOINT and CRIE_STORAGE_BUCKET must be set on the n8n instance (resolved from configuration/storage.yaml).');
}

// --- key: originals/{yyyy}/{mm}/{dd}/{documentId}/{sha256}.{ext} ---
const storageKey = 'originals/' + row.uploaded_partition + '/' + row.document_id + '/' + row.sha256 + '.' + ext;

return [{
  json: {
    correlationId: trig.correlationId || null,
    documentId: row.document_id,
    sha256: row.sha256,
    storageKey,
    storageBucket: bucket,
    storageEndpoint: endpoint,
    contentType,
    byteSize,
    hasExistingKey: !!row.storage_key,
    existingStorageKey: row.storage_key || null
  },
  binary: $input.first().binary
}];

// M2 verify-on-write: the object we just stored must report the size we sent.
const prep = $('Prepare Object').item.json;
const info = $json || {};
const reported = Number(info.size ?? (info.metadata && info.metadata.size));

if (!Number.isFinite(reported)) {
  throw new Error('SW-029: could not read a size back for ' + prep.storageKey + ' — refusing to record an unverified storage_key.');
}
if (reported !== prep.byteSize) {
  throw new Error('SW-029: stored size ' + reported + ' != uploaded size ' + prep.byteSize +
    ' for ' + prep.storageKey + ' — refusing to record a storage_key for a corrupt object.');
}

return [{ json: { ...prep, verifiedBytes: reported } }];

// Terminal node. Reached by two MUTUALLY EXCLUSIVE paths (uploaded / skipped),
// so it reads only $json — the current branch's item — and never reaches across
// branches. See docs/IMPLEMENTATION_NOTES.md 'Execution semantics'.
const prep = $('Prepare Object').item.json;
const j = $json || {};
const skipped = !j.stored_at;

return [{ json: {
  workflow_id: 'SW-029',
  correlationId: prep.correlationId,
  documentId: prep.documentId,
  sha256: prep.sha256,
  storageKey: skipped ? prep.existingStorageKey : j.storage_key,
  storageBucket: skipped ? prep.storageBucket : j.storage_bucket,
  contentType: skipped ? prep.contentType : j.content_type,
  byteSize: skipped ? prep.byteSize : Number(j.byte_size),
  storedAt: skipped ? null : j.stored_at,
  skippedUpload: skipped
} }];
